/// The protocol version a later protocol upgrade's requests need.
const V14: u32 = PROTOCOL_VERSION_14;
/// The protocol version before that upgrade.
const V13: u32 = PROTOCOL_VERSION_13;
/// The version `epoch-probe-newer.bin` is signed as: newer than any build knows.
const NEWER: u32 = 1_000;

fn vectors() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../rs-drive-proof-verifier/tests/vectors/protocol-gate")
}

fn vector<M: Message + Default>(name: &str) -> M {
    M::decode(std::fs::read(vectors().join(name)).unwrap().as_slice()).unwrap()
}

/// Knows no contracts or tokens, and answers the vectors' test quorum key.
struct Provider;
impl ContextProvider for Provider {
    fn get_data_contract(
        &self,
        _: &Identifier,
        _: &PlatformVersion,
    ) -> Result<Option<Arc<DataContract>>, ContextProviderError> {
        Ok(None)
    }
    fn get_token_configuration(
        &self,
        _: &Identifier,
    ) -> Result<Option<TokenConfiguration>, ContextProviderError> {
        Ok(None)
    }
    fn get_quorum_public_key(
        &self,
        kind: u32,
        quorum: [u8; 32],
        _: u32,
    ) -> Result<[u8; 48], ContextProviderError> {
        assert_eq!((kind, quorum), (106, [2; 32]));
        Ok(std::fs::read(vectors().join("quorum-key.bin"))
            .unwrap()
            .try_into()
            .unwrap())
    }
    fn get_platform_activation_height(&self) -> Result<CoreBlockHeight, ContextProviderError> {
        Ok(1)
    }
}

/// Knows no quorum keys, as a host's provider that cannot reach its quorum source.
struct NoQuorumKeys;
impl ContextProvider for NoQuorumKeys {
    fn get_data_contract(
        &self,
        _: &Identifier,
        _: &PlatformVersion,
    ) -> Result<Option<Arc<DataContract>>, ContextProviderError> {
        Ok(None)
    }
    fn get_token_configuration(
        &self,
        _: &Identifier,
    ) -> Result<Option<TokenConfiguration>, ContextProviderError> {
        Ok(None)
    }
    fn get_quorum_public_key(
        &self,
        _: u32,
        _: [u8; 32],
        _: u32,
    ) -> Result<[u8; 48], ContextProviderError> {
        Err(ContextProviderError::InvalidQuorum(
            "no quorum keys here".to_string(),
        ))
    }
    fn get_platform_activation_height(&self) -> Result<CoreBlockHeight, ContextProviderError> {
        Ok(1)
    }
}

/// The node every answer comes from. It is in the SDK's address list, so a ban shows.
fn node() -> Address {
    "http://127.0.0.1:9000".parse().unwrap()
}

/// A testnet mock SDK that enforces the gate, seeded (or pinned) at `seed`, that has
/// verified answers signed up to `verified` (0: none yet).
fn mock_sdk(seed: u32, pinned: bool, verified: u32) -> Sdk {
    sdk_with_proofs(seed, pinned, verified, true)
}

fn sdk_with_proofs(seed: u32, pinned: bool, verified: u32, proofs: bool) -> Sdk {
    sdk_with_provider(seed, pinned, verified, proofs, Provider)
}

fn sdk_with_provider<C: ContextProvider + 'static>(
    seed: u32,
    pinned: bool,
    verified: u32,
    proofs: bool,
    provider: C,
) -> Sdk {
    let version = PlatformVersion::get(seed).unwrap();
    let builder = SdkBuilder::new_mock()
        .with_network(dpp::dashcore::Network::Testnet)
        .with_context_provider(provider)
        .with_proofs(proofs)
        // The vectors are signed at height 10, mock expectations at 0.
        .with_height_tolerance(None);
    let builder = if pinned {
        builder.with_version(version)
    } else {
        builder.with_initial_version(version)
    };
    let sdk = builder.build().unwrap().with_protocol_gate_enforced();
    sdk.verified_protocol_version
        .store(verified, Ordering::Relaxed);
    let mut addresses = sdk.address_list().clone();
    addresses.add(node());
    sdk
}

fn dapi(sdk: &Sdk) -> &Arc<Mutex<MockDapiClient>> {
    let SdkInstance::Mock { dapi, .. } = &sdk.inner else {
        panic!("mock")
    };
    dapi
}

/// The node answers `request` with `answer`.
async fn answer<R>(sdk: &Sdk, request: &R, answer: Result<R::Response, Status>)
where
    R: TransportRequest + Mockable,
    R::Response: Mockable,
{
    let result = match answer {
        Ok(inner) => Ok(ExecutionResponse {
            inner,
            address: node(),
            retries: 0,
        }),
        Err(status) => Err(ExecutionError {
            inner: DapiClientError::Transport(TransportError::Grpc(status)),
            address: Some(node()),
            retries: 0,
        }),
    };
    dapi(sdk).lock().await.expect(request, &result).unwrap();
}

/// How many times `request` reached the node.
async fn sent<R: Mockable>(sdk: &Sdk, request: &R) -> usize {
    dapi(sdk).lock().await.request_count(request)
}

/// The genesis epoch, which the SDK asks for to learn the network's protocol version.
fn probe_request() -> GetEpochsInfoRequest {
    GetEpochsInfoRequest {
        version: Some(get_epochs_info_request::Version::V0(
            get_epochs_info_request::GetEpochsInfoRequestV0 {
                start_epoch: Some(0),
                count: 1,
                ascending: true,
                prove: true,
            },
        )),
    }
}

/// The node answers the probe with the genesis epoch signed as `signed`
/// (`pv13`, `pv14` or `newer`).
async fn answer_probe(sdk: &Sdk, signed: &str) {
    let response: GetEpochsInfoResponse = vector(&format!("epoch-probe-{signed}.bin"));
    answer(sdk, &probe_request(), Ok(response)).await;
}

async fn probes(sdk: &Sdk) -> usize {
    sent(sdk, &probe_request()).await
}

fn verified(sdk: &Sdk) -> u32 {
    sdk.verified_protocol_version.load(Ordering::Relaxed)
}

/// One attempt, so every request reaches the node once.
fn once() -> RequestSettings {
    RequestSettings {
        retries: Some(0),
        ..Default::default()
    }
}

/// `result` is the gate's refusal of `method`, with the network proven at `network`, by an
/// SDK `pinned` below the version or not.
fn assert_refused<T: std::fmt::Debug>(
    result: Result<T, Error>,
    method: &str,
    network: u32,
    pinned: bool,
    context: &str,
) {
    match result {
        Err(Error::ProtocolVersionNotActive {
            method: refused,
            required,
            network: proven,
            pinned: refused_for_pin,
            cause: None,
        }) => {
            assert_eq!(
                (refused, required, proven, refused_for_pin),
                (method, V14, network, pinned),
                "{context}"
            );
        }
        other => panic!("{context}: expected a refusal of {method}, got {other:?}"),
    }
}

fn fee_pots() -> GetContractFeePotsRequest {
    Identifier::new([7; 32])
        .query(&QuerySettings {
            request_settings: &RequestSettings::default(),
            protocol_version: PlatformVersion::latest(),
            verified_protocol_version: 0,
            prove: true,
        })
        .unwrap()
}

/// `sdk.mock()` borrows the SDK mutably; the gated requests are registered up front.
async fn expect_fee_pots(sdk: &mut Sdk) {
    sdk.mock()
        .expect_fetch(fee_pots(), None::<ContractFeePots>)
        .await
        .unwrap();
}

fn dpns() -> Arc<DataContract> {
    Arc::new(
        load_system_data_contract(SystemDataContract::DPNS, PlatformVersion::latest()).unwrap(),
    )
}

fn plain_query() -> DocumentQuery {
    DocumentQuery::new(dpns(), "domain").unwrap().with_limit(10)
}

/// Domains with their owners' preorders: a page with a sub-query bound to it.
